const fonte = $('Entrada').item.json.fonte;
const coleta = $('Abrir execução').item.json;
const resultado = $json ?? {};
const linhas = Array.isArray(resultado.linhas) ? resultado.linhas : [];
const falhas = Array.isArray(resultado.falhas) ? resultado.falhas : [];
const falha = falhas[0] ?? null;
const semDados = falha?.causa === 'sem_dados_no_periodo';
const sucesso = !falha || semDados;

const qualidadeResumo = {
  fontesEsperadas: 1,
  fontesColetadas: sucesso ? 1 : 0,
  faltantes: falha ? [{ fonte: fonte.nome || fonte.externalId, causa: falha.causa, detalhe: falha.detalhe ?? null }] : [],
  paridade: [],
  volumetria: resultado.volumetria ?? { linhas: linhas.length, bytes: 0, requests: resultado.requests ?? 0, duracaoMs: 0 },
};

return {
  json: {
    coletaId: coleta.id,
    status: sucesso ? 'success' : 'failed',
    errorCode: sucesso ? null : falha.causa,
    errorMessage: sucesso ? null : (falha.detalhe ?? falha.causa),
    requestCount: resultado.requests ?? 0,
    linhas,
    qualidadeResumo,
  },
};

const fonte = $('Entrada').item.json.fonte;
const coleta = $json;
const temColeta = Boolean(coleta?.id);

const qualidadeResumo = {
  fontesEsperadas: 1,
  fontesColetadas: 0,
  faltantes: [{ fonte: fonte.nome || fonte.externalId, causa: 'sem_credencial', detalhe: 'Conexão sem coletor provisionado no n8n.' }],
  paridade: [],
  volumetria: { linhas: 0, bytes: 0, requests: 0, duracaoMs: 0 },
};

return {
  json: {
    coletaId: temColeta ? coleta.id : null,
    temColeta,
    status: 'failed',
    errorCode: 'sem_credencial',
    errorMessage: 'Conexão sem coletor provisionado no n8n.',
    qualidadeResumo,
  },
};

const qualidade = $('Calcular qualidade').item.json;
const gravacao = $json ?? {};
const esperadas = qualidade.linhas.length;
const gravadas = Number(gravacao.linhasGravadas ?? 0);
const falhouGravacao = qualidade.status === 'success' && esperadas > 0 && gravadas !== esperadas;

return {
  json: {
    coletaId: qualidade.coletaId,
    status: falhouGravacao ? 'failed' : qualidade.status,
    requestCount: qualidade.requestCount,
    rowsReceived: esperadas,
    rowsWritten: gravadas,
    qualidadeResumo: qualidade.qualidadeResumo,
    errorCode: falhouGravacao ? 'gravacao_bq' : qualidade.errorCode,
    errorMessage: falhouGravacao ? (gravacao.detail ?? gravacao.title ?? 'gravação no BigQuery incompleta') : qualidade.errorMessage,
  },
};

const entrada = $('Entrada').item.json;
const coleta = $json ?? {};
const ok = coleta.status === 'success';
return {
  json: {
    fonteId: entrada.fonte.fonteId,
    platform: entrada.fonte.platform,
    nome: entrada.fonte.nome,
    janela: entrada.janela,
    tentativa: entrada.tentativa,
    ok,
    coletaId: coleta.id ?? null,
    status: coleta.status ?? 'erro_api',
    rowsReceived: coleta.rowsReceived ?? 0,
    rowsWritten: coleta.rowsWritten ?? 0,
    errorCode: coleta.errorCode ?? (ok ? null : coleta.title ?? 'erro_api'),
    errorMessage: coleta.errorMessage ?? (ok ? null : coleta.detail ?? null),
  },
};
